                result = clamp(float4(surface, 1.),0.,1.) * texColor.a;
            } else if( int(amzp_shadingType) == 2 ) {         
                float l = directionalLighting(p,n);
                float3 tc = texColor.rgb / max(texColor.a,0.0001);
                float3 surface = tc * ambient + tc * amzp_lightColor.rgb * l * (1.-ambient);
                surface *= amzp_lightIntensity;
                float s = pow(l,spec);
                surface = mix(surface*(1.-shine*0.1),float3(1.),shine*s);
                result = clamp(float4(surface, 1.),0.,1.) * texColor.a;
            }

            return result;
        }


        float4 evaluatePixelXy(float2 srcXy, float4 texColor) {
            float2 imageSize = screen.zw;

            float2 slope = float2(0.);
            float2 dx = float2(2.0,0.0);
            float2 dy = float2(0.0,2.0);
            float floatSamples = float(amzp_samples);
            int intSamples = int(amzp_samples);

            for(int i = -intSamples; i < intSamples; i++) {
                float n = float(i);
                slope.x += sampleDistortLuma(srcXy+dx*(n-0.5)) - sampleDistortLuma(srcXy+dx*n+(0.5));
                slope.y += sampleDistortLuma(srcXy+dy*(n-0.5)) - sampleDistortLuma(srcXy+dy*n+(0.5));
            }
            slope /= floatSamples;

            float3 p = float3(slope,-0.5);
            float3 n = normalize(p);

            float2 sourceXy = srcXy + slope * amzp_featureSize * amzp_refraction;
            float2 aberrXy = slope * amzp_featureSize * amzp_aberration;

            float4 result = chromatizePixel(sourceXy,aberrXy,texColor);

            result.a = 1.0;
            result = clamp(result,0.,1.);

            return applyShading(result,p,n);
        }

        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            if( amzPass==1 ) {
                float4 result = texColor;
                if( !(amzp_useLumaHeight>0.5) ) {
                    result.rgb = float3(result.a);
                }
                if( abs(amzp_roughness) > 0.0001 ) {
                    float2 st = amzLayerNorm();
                    st.x *= layer.x/layer.y;
                    float scale = 0.15 * amzp_roughnessScale;
                    int OCTAVES = 2;
                    float2 parallax = float2(0.,0.);
                    float p;
                    if( amzp_roughness < 0.0 ) {
                        p = (turbulence((st-0.5)/scale+0.5, OCTAVES, parallax, amzp_evolution + 7391.935*amzp_seed)) * (-amzp_roughness/3.);
                    } else {
                        p = (1.-turbulence((st-0.5)/scale+0.5, OCTAVES, parallax, amzp_evolution + 7391.935*amzp_seed)) * (amzp_roughness/3.);
                    }
                    result.rgb *= (1.-p);
                }
                amzOutput = result;
            } else {
                amzOutput = evaluatePixelXy(amzScreenNorm()*screen.zw,texColor) * texColor.a;
            }
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
